BEGIN;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.organizations FROM PUBLIC,anon,authenticated;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profiles FROM PUBLIC,anon,authenticated;
ALTER TABLE public.organization_memberships ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.organization_memberships FROM PUBLIC,anon,authenticated;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.courses FROM PUBLIC,anon,authenticated;
ALTER TABLE public.file_assets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_assets FROM PUBLIC,anon,authenticated;
ALTER TABLE public.course_modules ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.course_modules FROM PUBLIC,anon,authenticated;
ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.lessons FROM PUBLIC,anon,authenticated;
ALTER TABLE public.enrollments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.enrollments FROM PUBLIC,anon,authenticated;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.announcements FROM PUBLIC,anon,authenticated;
ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.materials FROM PUBLIC,anon,authenticated;
ALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.calendar_events FROM PUBLIC,anon,authenticated;
ALTER TABLE public.calendar_event_attendees ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.calendar_event_attendees FROM PUBLIC,anon,authenticated;
ALTER TABLE public.certificate_issues ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.certificate_issues FROM PUBLIC,anon,authenticated;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.audit_events FROM PUBLIC,anon,authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA private FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN
 FOR t IN SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='private' LOOP
  EXECUTE format('ALTER TABLE private.%I ENABLE ROW LEVEL SECURITY',t);
 END LOOP;
END $$;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT SELECT ON public.organizations,public.organization_memberships,public.courses,public.course_modules,public.lessons,public.enrollments,public.announcements,public.materials,public.calendar_events,public.calendar_event_attendees,public.file_assets,public.certificate_issues,public.audit_events TO authenticated;
GRANT SELECT(id,display_name,status,created_at,updated_at,row_version) ON public.profiles TO authenticated;
CREATE POLICY organizations_read ON public.organizations FOR SELECT TO authenticated USING(private.member_id(id) IS NOT NULL);
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=private.self_profile_id());
CREATE POLICY memberships_read ON public.organization_memberships FOR SELECT TO authenticated USING(profile_id=private.self_profile_id() OR private.org_admin(organization_id));
CREATE POLICY courses_read ON public.courses FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR private.course_access(organization_id,id));
CREATE POLICY modules_read ON public.course_modules FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR (status='published' AND private.course_access(organization_id,course_id)));
CREATE POLICY lessons_read ON public.lessons FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR private.lesson_access(organization_id,id));
CREATE POLICY enrollments_read ON public.enrollments FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR membership_id=private.member_id(organization_id));
CREATE POLICY announcements_read ON public.announcements FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR (status='published' AND published_at<=now() AND private.course_access(organization_id,course_id)));
CREATE POLICY materials_read ON public.materials FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR private.material_access(organization_id,id));
CREATE POLICY events_read ON public.calendar_events FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR private.event_access(organization_id,id));
CREATE POLICY attendees_read ON public.calendar_event_attendees FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR (membership_id=private.member_id(organization_id) AND status='active' AND private.event_access(organization_id,event_id)));
CREATE POLICY assets_read ON public.file_assets FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR private.asset_access(organization_id,id));
CREATE POLICY certificates_read ON public.certificate_issues FOR SELECT TO authenticated USING(private.org_admin(organization_id) OR private.certificate_access(organization_id,id));
CREATE POLICY audit_read ON public.audit_events FOR SELECT TO authenticated USING(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,slug,title,description,tag,status,sort_order,price_amount,currency,declared_lesson_count,cover_asset_id) ON public.courses TO authenticated;
CREATE POLICY courses_insert ON public.courses FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,title,sort_order,status) ON public.course_modules TO authenticated;
CREATE POLICY course_modules_insert ON public.course_modules FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,module_id,title,description,video_url,live_url,duration_minutes,sort_order,status,scheduled_start_hint) ON public.lessons TO authenticated;
CREATE POLICY lessons_insert ON public.lessons FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,membership_id,status,enrolled_at,progress_percent,completed_at) ON public.enrollments TO authenticated;
CREATE POLICY enrollments_insert ON public.enrollments FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,title,body,published_at,status) ON public.announcements TO authenticated;
CREATE POLICY announcements_insert ON public.announcements FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,lesson_id,title,external_url,file_asset_id,sort_order,status) ON public.materials TO authenticated;
CREATE POLICY materials_insert ON public.materials FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,lesson_id,title,module_label,starts_at,ends_at,timezone,color_key,status) ON public.calendar_events TO authenticated;
CREATE POLICY calendar_events_insert ON public.calendar_events FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id));
GRANT INSERT(id,organization_id,course_id,purpose,bucket_name,object_path,original_name,mime_type,size_bytes,sha256,status) ON public.file_assets TO authenticated;
CREATE POLICY file_assets_insert ON public.file_assets FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id) AND status='pending');
GRANT INSERT(id,organization_id,enrollment_id,course_id,membership_id,serial,issued_at,status,snapshot,file_asset_id) ON public.certificate_issues TO authenticated;
CREATE POLICY certificate_issues_insert ON public.certificate_issues FOR INSERT TO authenticated WITH CHECK(private.org_admin(organization_id) AND status='draft');
CREATE POLICY courses_update ON public.courses FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY file_assets_update ON public.file_assets FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY course_modules_update ON public.course_modules FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY lessons_update ON public.lessons FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY enrollments_update ON public.enrollments FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY announcements_update ON public.announcements FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY materials_update ON public.materials FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY calendar_events_update ON public.calendar_events FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY calendar_event_attendees_update ON public.calendar_event_attendees FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
CREATE POLICY certificate_issues_update ON public.certificate_issues FOR UPDATE TO authenticated USING(private.org_admin(organization_id)) WITH CHECK(private.org_admin(organization_id));
-- UPDATE/DELETE/TRUNCATE no se conceden directamente. Toda actualización usa CAS específico.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA private FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION private.self_profile_id(),private.actor_profile_id(),private.member_id(uuid),private.org_admin(uuid),private.course_access(uuid,uuid),private.lesson_access(uuid,uuid),private.material_access(uuid,uuid),private.event_access(uuid,uuid),private.certificate_access(uuid,uuid),private.asset_access(uuid,uuid),private.allowed_url(text) TO authenticated;
-- Los CHECK JSON necesitan EXECUTE, pero el helper es puro y no devuelve información.
GRANT EXECUTE ON FUNCTION private.no_secret_keys(jsonb) TO authenticated;
COMMIT;
